"""Validate raw records, aggregate seed medians, generate paper artifacts."""
from pathlib import Path
import csv,json,hashlib,statistics as st,sys,subprocess
H=Path(__file__).resolve().parent;ROOT=H.parents[1];OUT=H/'results';MAN=ROOT/'docs/manuscript'
p=json.loads((H/'protocol.json').read_text());meta=json.loads((OUT/'metadata.json').read_text())
assert meta['completed'] and hashlib.sha256((OUT/'raw_results.csv').read_bytes()).hexdigest()==meta['raw_sha256']
assert hashlib.sha256((H/'protocol.json').read_bytes()).hexdigest()==meta['protocol_sha256']
rows=list(csv.DictReader((OUT/'raw_results.csv').open()))
keys={(r['scenario'],int(r['n_old']),int(r['seed']),int(r['repeat'])) for r in rows}
expected={(c,n,s,r) for c in p['scenarios'] for n in p['sizes'] for s in p['seeds'] for r in range(p['repetitions'])}
assert keys==expected and len(rows)==len(expected)
for r in rows:
 assert r['correctness_pass']=='True'
 for k in ['delta_error','weight_error','symmetry_error','batch_delta_error','batch_weight_error']:assert float(r[k])<=p['tolerance']
 for prefix in ['inc','batch']:
  assert abs(sum(float(r[f'{prefix}_{k}_ms']) for k in ['delta','bookkeeping','w'])-float(r[f'{prefix}_total_ms']))<1e-9
labels={'ring_control':'Ring: control','ring_enemy':'Ring: enemy','star_leaf':'Star: leaf','star_hub':'Star: hub'}
summary=[]
for n in p['sizes']:
 for c in p['scenarios']:
  group=[r for r in rows if r['scenario']==c and int(r['n_old'])==n]
  vals={k:[] for k in ['inc_total','batch_total','inc_delta','inc_w','inc_bookkeeping','ratio']}
  for seed in p['seeds']:
   a=[r for r in group if int(r['seed'])==seed]
   for k in list(vals)[:-1]:vals[k].append(st.median(float(r[k+'_ms']) for r in a))
   vals['ratio'].append(vals['batch_total'][-1]/vals['inc_total'][-1])
  item=dict(scenario=c,n_old=n,shrink=int(group[0]['shrink']),touch=int(group[0]['touch']),q_touch=int(group[0]['q_touch']))
  for k,v in vals.items():item[k+'_mean']=st.mean(v);item[k+'_sd']=st.pstdev(v)
  summary.append(item)
with (OUT/'summary.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=summary[0]);w.writeheader();w.writerows(summary)
def pm(r,k):return '$'+f"{r[k+'_mean']:.2f} \\pm {r[k+'_sd']:.2f}"+'$'
with (OUT/'table.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['Scenario','$n$','$|\\mathcal{T}_{adj}|$','$Q_{\\mathcal{T}}$','Inc. (ms)','Batch (ms)','Batch/inc.'])
 for r in summary:w.writerow([labels[r['scenario']],r['n_old'],r['touch'],r['q_touch'],pm(r,'inc_total'),pm(r,'batch_total'),pm(r,'ratio')])
cmd=[sys.executable,str(ROOT/'experiments/build_tables_from_csv.py'),'--csv',str(OUT/'table.csv'),'--output',str(MAN/'tables/tab_locality_stress.tex'),'--caption',r'Controlled locality stress tests with $n$ nodes before insertion. Timings and batch/incremental ratios report mean $\pm$ population SD across five seeds, using five timing repetitions per seed. Ratios below one indicate a slower incremental update.','--label','tab:locality-stress','--note',r'Each repetition starts from the same initial state. Latency includes feature/label append, CSR extension and weight writes; initialization, state cloning and correctness checks are excluded. Per-seed latency is the median over repetitions; each speedup is a ratio of these medians. CPU thread limits are set to one.','--note',r'The enemy insertion shrinks $n/2$ radii; the other cases shrink none. Ring controls attach to a regular node; star insertions attach to a leaf or the hub. Features are controlled Euclidean coordinates without normalization. These synthetic, single-insertion tests are separate from the citation and OGB protocols.']
subprocess.run(cmd,check=True)
# Numerical prose macros from the same validated CSV aggregation.
def get(n,c):return next(r for r in summary if r['n_old']==n and r['scenario']==c)
low=get(p['sizes'][0],'ring_enemy'); hub=get(p['sizes'][0],'star_hub');large=get(p['sizes'][-1],'star_hub');leaf=get(p['sizes'][-1],'star_leaf')
mac={'StressCases':str(len(expected)//p['repetitions']),'StressRepeats':str(p['repetitions']),'StressSeeds':str(len(p['seeds'])),'StressMinN':str(p['sizes'][0]),'StressMaxN':str(p['sizes'][-1]),'StressEnemyRatio':f"{low['ratio_mean']:.2f}",'StressHubRatio':f"{hub['ratio_mean']:.2f}",'StressLargeHubMs':f"{large['inc_total_mean']:.2f}",'StressLargeLeafMs':f"{leaf['inc_total_mean']:.2f}"}
text='% Auto-generated by experiments/locality_stress/summarize.py — do not edit by hand\n% Source: experiments/locality_stress/results/raw_results.csv\n'
for k,v in mac.items():text+='\\newcommand{\\'+k+'}{'+v+'}\n'
(MAN/'tables/locality_stress_numbers.tex').write_text(text)
errs={k:max(float(r[k]) for r in rows) for k in ['delta_error','weight_error','batch_delta_error','batch_weight_error','symmetry_error']}
report='# Locality stress test — results\n\nProtocol frozen before execution; '+str(len(expected))+' timing records from '+str(len(expected)//p['repetitions'])+' graph/seed cases. All correctness checks pass at tolerance 1e-9. Five timing repetitions are repeated measurements of each case, not additional independent graph trials.\n\n| Scenario | n | S | T | Q | Inc ms | Batch ms | Batch/inc |\n|---|---:|---:|---:|---:|---:|---:|---:|\n'
for r in summary:report+=f"| {labels[r['scenario']]} | {r['n_old']} | {r['shrink']} | {r['touch']} | {r['q_touch']} | {r['inc_total_mean']:.3f} | {r['batch_total_mean']:.3f} | {r['ratio_mean']:.3f} |\n"
report+='\nMax errors: `'+json.dumps(errs)+'`.\n\nIncremental loses to vectorized batch in the two adverse cases at the smallest size. At larger sizes the batch radius rebuild dominates again, while adverse-case incremental latency remains substantially higher than control latency. The star comparison isolates total degree: both cases have touch size 2 and no radius shrink, yet Q differs from 3 to n+1. The ring enemy case demonstrates a shrink set of n/2 and therefore refutes any universal small-touch-set assumption.\n\nThese are controlled synthetic geometries, with one insertion per fresh state; no claim about natural arrival frequencies, long-stream reliability, or classifier accuracy follows. All timings are implementation-specific. Suite peak RSS includes initialization and verification, and is not an insertion-memory measurement: '+str(meta['suite_peak_rss_bytes'])+' bytes. Thread limits were requested through environment variables; this is not an instrumented proof of active BLAS thread count. Hardware/software metadata and hashes are in results/metadata.json.\n'
(ROOT/'docs/locality_stress_results_2026-09-11.md').write_text(report)
print(report)
